package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "simple wrap",
			text:  "hello world",
			width: 10,
			want:  []string{"hello", "world"},
		},
		{
			name:  "fits on one line",
			text:  "hello world",
			width: 20,
			want:  []string{"hello world"},
		},
		{
			name:  "word longer than width",
			text:  "superlongword short",
			width: 5,
			want:  []string{"superlongword", "short"},
		},
		{
			name:  "multiple long words",
			text:  "abc def ghi",
			width: 2,
			want:  []string{"abc", "def", "ghi"},
		},
		{
			name:  "whitespace only input",
			text:  "   ",
			width: 5,
			want:  nil,
		},
		{
			name:  "empty input",
			text:  "",
			width: 5,
			want:  nil,
		},
		{
			name:  "zero width",
			text:  "hello",
			width: 0,
			want:  nil,
		},
		{
			name:  "negative width",
			text:  "hello",
			width: -1,
			want:  nil,
		},
		{
			name:  "collapses whitespace",
			text:  "hello   world\tfoo",
			width: 10,
			want:  []string{"hello", "world", "foo"},
		},
		{
			name:  "no leading or trailing spaces",
			text: "  hello world  ",
			width: 10,
			want: []string{"hello", "world"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == 0 && got == nil && tt.want == nil {
				return
			}
			if len(got) != len(tt.want) {
				t.Fatalf("got %d lines, want %d: %v", len(got), len(tt.want), got)
			}
			for i, w := range tt.want {
				if got[i] != w {
					t.Errorf("line %d: got %q, want %q", i, got[i], w)
				}
			}
		})
	}
}

